(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const setV = (el, v) => { const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value').set; d.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
  const tab = (name) => [...document.querySelectorAll('.pc-tab')].find((b) => b.textContent.includes(name));
  const out = {};

  const nameInput = document.querySelector('.tb-card .tb-input');
  setV(nameInput, '卍解示例 · STM32 避障小车');
  [...document.querySelectorAll('.tb-diff-opt')].find((b) => b.textContent.includes('卍解'))?.click();
  await sleep(300);
  [...document.querySelectorAll('.tb-btn-primary')].find((b) => b.textContent.includes('创建'))?.click();
  for (let i = 0; i < 20; i++) { await sleep(500); if (document.querySelector('.pc-wrap')) break; }

  // 代码：两条（主程序 + 头文件），演示分组
  [...document.querySelectorAll('.pc-btn')].find((b) => b.textContent.includes('直接贴代码'))?.click();
  await sleep(700);
  let ins = [...document.querySelectorAll('.pc-input')];
  setV(ins[0], 'main.c');
  setV(ins[1], '主程序：测距 + 转向');
  setV(document.querySelector('.pc-textarea'), '#include "stm32f10x.h"\n#include "delay.h"\n\n// 主函数：前方 20cm 内有东西就转弯\nint main(void)\n{\n    Delay_Init();\n    Ultra_Init();\n    while (1)\n    {\n        u16 cm = Ultra_GetDistance();\n        if (cm < 20) { Motor_Turn(120); }\n        else         { Motor_Go(90);    }\n        Delay_ms(50);\n    }\n}\n');
  [...document.querySelectorAll('.pc-btn-primary')].find((b) => b.textContent.includes('放进作品'))?.click();
  await sleep(2000);

  // 接线表两行
  tab('接线表')?.click();
  await sleep(600);
  const addPin = async (m, p, b, n) => {
    const x = [...document.querySelectorAll('.pc-inline-form .pc-input')];
    setV(x[0], m); setV(x[1], p); setV(x[2], b); setV(x[3], n);
    [...document.querySelectorAll('.pc-btn-primary')].find((y) => y.textContent.includes('加一行'))?.click();
    await sleep(1400);
  };
  await addPin('超声波 HC-SR04', 'TRIG', 'PA0', '触发');
  await addPin('超声波 HC-SR04', 'ECHO', 'PA1', '回波，5V 要分压');
  await addPin('L298N 驱动', 'IN1', 'PB6', '左轮方向');

  // 回到代码页截图
  tab('程序代码')?.click();
  await sleep(900);
  document.querySelector('.pc-wrap')?.scrollIntoView({ block: 'start' });
  await sleep(700);
  out.tabs = [...document.querySelectorAll('.pc-tab')].map((b) => b.textContent.trim());
  out.codeItems = [...document.querySelectorAll('.pc-item-name')].map((e) => e.textContent);
  return JSON.stringify(out);
})()
